            float2 texScaleVec = float2(1./amzp_texRepeatX,1./amzp_texRepeatY);
            texCoord *= texRot;
            texCoord += amzp_texOffset / 1000.0;
            texCoord /= texScaleVec;
            if( (amzp_mirror>0.5) ) {
                texCoord = abs(mod(texCoord,2.0)-1.0);
            } else {
                texCoord = mod(texCoord, 1.);
            }
            texCoord -= 0.5;
            texCoord = texCoord * (1.-5./screen.zw);
            texCoord *= amzp_texCrop;
            texCoord *= texTwirlRot;
            texCoord += 0.5;
            return texCoord;
        }
        void amzRender(){amzVertex_main();
            float2 st = amzLayerNorm();
            st -= 0.5;
            st.x *= layer.x/layer.y;
            st /= amzp_scale;
            float3 ro = float3(0., 1., -1.);
            float3 rd = normalize(float3(st, 1.));
            float d = march(ro,rd);
            float3 p = ro + rd * d;
            float3 n = calcNormal(p);
         float3 nn = n;
         float l = lighting(p,n);
            float4 localCoord = float4(p-(amzp_position/100.), 1.);
            n = (float4(n,0.) * orientAndRotate).xyz;
            localCoord *= orientAndRotate;
            float4 pp = localCoord;
         float4 qq = pp * (vecToVec(n,pp.xyz*float3(0.,1.,0.)));
            if( (amzp_texStretch>0.5) ) {
                pp /= float4(amzp_width,amzp_height,amzp_depth,1.);
            }
            float2 texCoord;
            float a;
            if( n.x > 0.5 ) {
                texCoord = ((pp.zy+1.)/2.);
                a = amzp_height<0.0105 || amzp_depth<0.0105 ? 0.0 : 1.0;
            } else if ( n.x < -0.5 ) {
                texCoord = ((pp.zy+1.)/2.);
                texCoord.x = 1.-texCoord.x;
                a = amzp_height<0.0105 || amzp_depth<0.0105 ? 0.0 : 1.0;
            } else if ( n.y > 0.5 ) {
                texCoord = ((pp.xz+1.)/2.);
                a = amzp_width<0.0105 || amzp_depth<0.0105 ? 0.0 : 1.0;
            } else if ( n.y < -0.5 ) {
                texCoord = 1.-((pp.xz+1.)/2.);
                texCoord.x = 1.-texCoord.x;
                a = amzp_width<0.0105 || amzp_depth<0.0105 ? 0.0 : 1.0;
            } else if ( n.z > 0.5 ) {
                texCoord = (pp.xy+1.)/2.;
                texCoord.x = 1.-texCoord.x;
                a = amzp_width<0.0105 || amzp_height<0.0105 ? 0.0 : 1.0;
            } else if ( n.z < -0.5 ) {
                texCoord = (pp.xy+1.)/2.;
                a = amzp_width<0.0105 || amzp_height<0.0105 ? 0.0 : 1.0;
            } else {
                texCoord = float2(0.,0.);
                a = 1.0;
            }
            texCoord = mapTexture(texCoord);
         float4 texColor = amzTexture( 0, (float4(texCoord,0.0,1.0)*amzLayerToScreen()).xy );
            amzOutput = applyShading(texColor, p, nn, d) * a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

