function animate(env,el,p) {
    let groups = [];

    if( p.thick < 0.0001 ) {
        groups.push(3);
    } else if( (p.leftMode == 0 || p.leftMode == 1) &&
        (p.bottomMode == 0 || p.bottomMode == 1) &&
        (p.frontMode == 0 || p.frontMode == 1) &&
        (p.rightMode == 0 || p.rightMode == 1) &&
        (p.topMode == 0 || p.topMode == 1) &&
        (p.backMode == 0 || p.backMode == 1) ) {
        if( p.shadingType == 1 ) {
            groups.push(2);
        } else {
            groups.push(1);
        }
    } else {
        groups.push(0);
    }

    el.shaderGroups = groups;
    return el;
}

